/** * FastWebTools Admin Dashboard - Cloudflare Worker * * v2.5.4: fixes 4 dashboard bugs reported by user: * 1. Comments tab article names now link to real blog posts (not home). * 2. Article Likes tab names now link to real blog posts. * 3. Daily Activity chart now reads /admin/daily-activity correctly * (activity[] with day+visits) and aggregates daily comment counts * so both lines show real 7-day data instead of flat zeros. * 4. Mobile sidebar drawer now has a solid background (dark or light * depending on theme) so nav text stays readable when it opens. */

const BACKEND_BASE = "https://fastwebtools-admin.formyworkupwork.workers.dev";
const REQUEST_TIMEOUT_MS = 10000;

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
  "Access-Control-Max-Age": "86400",
};

function jsonResponse(obj, status) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: Object.assign(
      { "Content-Type": "application/json;charset=UTF-8" },
      CORS_HEADERS
    ),
  });
}

async function fetchWithTimeout(env, path, options, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(
    () => controller.abort(),
    timeoutMs || REQUEST_TIMEOUT_MS
  );
  const finalOptions = Object.assign({}, options, {
    signal: controller.signal,
  });
  try {
    if (env && env.BACKEND && typeof env.BACKEND.fetch === "function") {
      return await env.BACKEND.fetch("https://internal" + path, finalOptions);
    }
    return await fetch(BACKEND_BASE + path, finalOptions);
  } finally {
    clearTimeout(timer);
  }
}

async function safeFetchJson(
  env,
  path,
  options,
  { retries = 1, timeoutMs = REQUEST_TIMEOUT_MS } = {}
) {
  let lastError = null;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const resp = await fetchWithTimeout(env, path, options, timeoutMs);
      const raw = await resp.text();
      let parsed = null;
      let parseOk = false;
      try {
        parsed = raw ? JSON.parse(raw) : null;
        parseOk = true;
      } catch (parseErr) {
        parseOk = false;
      }
      if (!resp.ok && resp.status >= 500 && attempt < retries) {
        lastError = new Error("Backend returned " + resp.status);
        continue;
      }
      return {
        networkOk: true,
        status: resp.status,
        ok: resp.ok,
        parseOk,
        data: parsed,
        raw,
        contentType: resp.headers.get("Content-Type") || "",
      };
    } catch (err) {
      lastError = err;
      if (attempt < retries) continue;
    }
  }
  return { networkOk: false, error: lastError };
}

async function handleLogin(request, env) {
  let username = "";
  let password = "";
  try {
    const body = await request.json();
    username = body.username || "";
    password = body.password || "";
  } catch (err) {
    return jsonResponse(
      { success: false, message: "Request body must be valid JSON." },
      400
    );
  }
  const result = await safeFetchJson(
    env,
    "/admin/login",
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password }),
    },
    { retries: 1 }
  );
  if (!result.networkOk) {
    return jsonResponse(
      {
        success: false,
        message:
          "Could not reach the authentication backend. Please try again shortly.",
      },
      502
    );
  }
  if (!result.parseOk) {
    return jsonResponse(
      {
        success: false,
        message:
          "Authentication backend returned an unexpected response (not JSON). This usually means the backend is unreachable or is returning an edge error page.",
      },
      502
    );
  }
  return jsonResponse(result.data, result.status);
}

async function handleProxy(request, url, env) {
  const targetPath = url.pathname.replace(/^\/api/, "/admin");
  const targetPathWithQuery = targetPath + url.search;
  const headers = {};
  const auth = request.headers.get("Authorization");
  if (auth) headers["Authorization"] = auth;
  const ct = request.headers.get("Content-Type");
  if (ct) headers["Content-Type"] = ct;
  let body;
  if (!["GET", "HEAD"].includes(request.method)) {
    try {
      body = await request.arrayBuffer();
    } catch (err) {
      return jsonResponse(
        { success: false, message: "Failed to read request body." },
        400
      );
    }
  }
  const result = await safeFetchJson(
    env,
    targetPathWithQuery,
    { method: request.method, headers, body },
    { retries: 1 }
  );
  if (!result.networkOk) {
    return jsonResponse(
      {
        success: false,
        message:
          "Could not reach the backend service. Please try again shortly.",
      },
      502
    );
  }
  if (result.parseOk) return jsonResponse(result.data, result.status);
  if (result.ok) {
    return new Response(result.raw, {
      status: result.status,
      headers: Object.assign(
        { "Content-Type": result.contentType || "text/plain;charset=UTF-8" },
        CORS_HEADERS
      ),
    });
  }
  return jsonResponse(
    {
      success: false,
      message:
        "Backend error (status " +
        result.status +
        "). The backend did not return a valid JSON response.",
      status: result.status,
    },
    result.status >= 400 ? result.status : 502
  );
}

async function handleRequest(request, env) {
  const url = new URL(request.url);
  if (request.method === "OPTIONS")
    return new Response(null, { headers: CORS_HEADERS });
  if (url.pathname === "/api/login") return handleLogin(request, env);
  if (url.pathname.startsWith("/api/")) return handleProxy(request, url, env);
  return new Response(DASHBOARD_HTML, {
    headers: {
      "Content-Type": "text/html;charset=UTF-8",
      "Cache-Control": "no-store, no-cache, must-revalidate",
    },
  });
}

export default {
  async fetch(request, env, ctx) {
    try {
      return await handleRequest(request, env);
    } catch (err) {
      const url = new URL(request.url);
      if (url.pathname.startsWith("/api/")) {
        return jsonResponse(
          {
            success: false,
            message:
              "Internal server error: " +
              (err && err.message ? err.message : String(err)),
          },
          500
        );
      }
      return new Response("Internal Server Error", {
        status: 500,
        headers: { "Content-Type": "text/plain" },
      });
    }
  },
};

